  "Protezione dall'Energia": {"livello":3,"scuola":"Abiurazione","classi":["Artefice","Chierico","Druido","Mago","Ranger","Stregone"],"tempo":"1 Azione","gittata":"Tocco","conc":true,"desc":"Tocchi una creatura consenziente: per 1 ora (concentrazione) ottiene resistenza a un tipo di danno a scelta tra acido, freddo, fuoco, fulmine o tuono."},
  "Controllare Acqua": {"livello":4,"scuola":"Trasmutazione","classi":["Chierico","Druido","Mago"],"tempo":"1 Azione","gittata":"90m","area":"Cubo","conc":true,"desc":"Controlli una massa d'acqua in un cubo di 30m per 10 minuti (concentrazione): puoi creare un'inondazione travolgente, dividere le acque formando una trincea, deviare il corso o creare un vortice devastante (2d8 contundenti)."},
  "Dominare Bestie": {"livello":4,"scuola":"Ammaliamento","classi":["Druido","Stregone"],"tempo":"1 Azione","gittata":"18m","conc":true,"desc":"Prendi il controllo telepatico di una bestia entro 18m per 1 minuto (concentrazione; TS Saggezza con vantaggio se in combattimento): esegue qualsiasi tuo comando telepatico."},
  "Evocare Creature Boschive": {"livello":4,"scuola":"Evocazione","classi":["Druido","Ranger"],"tempo":"1 Azione","gittata":"18m","conc":true,"desc":"Evochi spiriti fatati che assumono la forma di creature boschive (1 GS 2, 2 GS 1, 4 GS 1/2 o 8 GS 1/4) per 1 ora (concentrazione): obbediscono fedelmente ai tuoi ordini verbali in combattimento."},
  "Insetto Gigante": {"livello":4,"scuola":"Trasmutazione","classi":["Druido"],"tempo":"1 Azione","gittata":"9m","conc":true,"desc":"Trasformi fino a 10 millepiedi, 3 ragni, 5 vespe o 1 scorpione entro 9m in versioni giganti fedeli ai tuoi comandi per 10 minuti (concentrazione)."},
  "Contagio": {"livello":5,"scuola":"Necromanzia","classi":["Chierico","Druido"],"tempo":"1 Azione","gittata":"Tocco","desc":"Attacco magico in mischia: avveleni il bersaglio. Se fallisce 3 TS Costituzione prima di 3 successi, contrae una malattia a scelta (febbre, cecità, decomposizione, brividi) della durata di 7 giorni."},
  "Guscio Antivita": {"livello":5,"scuola":"Abiurazione","classi":["Druido"],"tempo":"1 Azione","gittata":"Sé stesso (3m)","conc":true,"desc":"Una barriera scintillante di 3m di raggio ti circonda per 1 ora (concentrazione): impedisce a tutte le creature viventi (eccetto costrutti e non morti) di avvicinarsi o attraversarla."},
  "Reincarnazione": {"livello":5,"scuola":"Trasmutazione","classi":["Druido"],"tempo":"1 Ora","gittata":"Tocco","desc":"Tocchi un umanoide morto da non più di 10 giorni (consumando unguenti rari per 1.000 mo): forgi un nuovo corpo adulto con una razza determinata casualmente dal d100 e ne richiami l'anima in vita a pieni PF."},
  "Trasmutare Roccia": {"livello":5,"scuola":"Trasmutazione","classi":["Artefice","Druido","Mago"],"tempo":"1 Azione","gittata":"36m","area":"Cubo","desc":"In un cubo di 12m trasformi roccia in fango profondo (intrappola e rallenta il movimento di 4×) o fango in roccia solida (intrappola le creature nell'area; TS Forza per liberarsi)."},
